## 任务契约（已冻结）

- 源语言：C（按 C11 理解，纯可移植，无平台 #ifdef）；目标语言：**Go**（当前稳定 go 工具链，`package main`）。
- **同 OS 语言方向转换**：源与目标均在 Windows 构建；本例考的是 C 语言习惯→Go 语言习惯的映射，不掺跨 OS 系统面。
- 任务模式：多文件→单文件。把下面 3 份 C 文件（上游 RC4 模块 .c/.h + 薄 CLI 驱动 .c）整体转换为**一个** Go 源文件 `target.go`。
- 两侧编译命令：
  - 源侧基线（C11）：`gcc -std=c11 WjCryptLib_Rc4.c rc4_decrypt_cli.c -o program`
  - 目标侧（Go, Windows）：`go build -o program.exe`（单 package main，含 target.go）
- 场景：只读——按 hex key 对 hex 密文做 RC4 解密并把明文写 stdout。无网络、无文件写/删、无进程/命令执行。
- 须保留可观察行为：用法字符串、错误退出码（用法/hex 错误=2、RC4 初始化失败=1）、成功把明文原始字节写 stdout=0、RC4 KSA/PRGA/DropN 语义与上游一致（见 system 指令）。

## C → Go 映射指引（按需应用；这是本例考点，勿机械照搬 C 写法）

见 system 指令：头/预处理→包与导出、`#define` 宏→函数/元组交换、指针/字节缓冲/`void*`→`[]byte`、
定宽无符号与 mod-256→`byte`/`uint32` 显式转换、错误返回码→`error`+`os.Exit` 退出码、`argv`/hex→`os.Args`+`encoding/hex`、
**未使用 import/变量即编译错误**。（本项目 c-to-go Skill 尚不存在，故此处仅内联指引，不提供 Skill 快照。）

## 待转换的源（3 份 C 文件）

### 上游头文件 WjCryptLib_Rc4.h（逐字，被评译主体）
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  WjCryptLib_RC4
//
//  An implementation of RC4 stream cipher
//
//  This is free and unencumbered software released into the public domain - June 2013 waterjuice.org
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

#pragma once

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  IMPORTS
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

#include <stdint.h>

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  TYPES
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

// Rc4Context - This must be initialised using Rc4Initialised. Do not modify the contents of this structure directly.
typedef struct
{
    uint32_t     i;
    uint32_t     j;
    uint8_t      S[256];
} Rc4Context;

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  PUBLIC FUNCTIONS
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Initialise
//
//  Initialises an RC4 cipher and discards the specified number of first bytes. KeySize must be in the range 1 to 256
//  inclusive.
//  Returns 0 if successful, or -1 if KeySize is 0.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
int
    Rc4Initialise
    (
        Rc4Context*     Context,        // [out]
        void const*     Key,            // [in]
        uint32_t        KeySize,        // [in]
        uint32_t        DropN           // [in]
    );

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Output
//
//  Outputs the requested number of bytes from the RC4 stream
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void
    Rc4Output
    (
        Rc4Context*     Context,        // [in out]
        void*           Buffer,         // [out]
        uint32_t        Size            // [in]
    );

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Xor
//
//  XORs the RC4 stream with an input buffer and puts the results in an output buffer. This is used for encrypting
//  and decrypting data. InBuffer and OutBuffer can point to the same location for inplace encrypting/decrypting
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void
    Rc4Xor
    (
        Rc4Context*     Context,        // [in out]
        void const*     InBuffer,       // [in]
        void*           OutBuffer,      // [out]
        uint32_t        Size            // [in]
    );

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4XorWithKey
//
//  This function combines Rc4Initialise and Rc4Xor. This is suitable when encrypting/decrypting data in one go with a
//  key that is not going to be reused.
//  InBuffer and OutBuffer can point to the same location for inplace encrypting/decrypting.
//  Returns 0 if successful, or -1 if KeySize is 0.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
int
    Rc4XorWithKey
    (
        uint8_t const*      Key,                    // [in]
        uint32_t            KeySize,                // [in]
        uint32_t            DropN,                  // [in]
        void const*         InBuffer,               // [in]
        void*               OutBuffer,              // [out]
        uint32_t            BufferSize              // [in]
    );


### 上游实现 WjCryptLib_Rc4.c（逐字，被评译主体）
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  WjCryptLib_RC4
//
//  An implementation of RC4 stream cipher
//
//  This is free and unencumbered software released into the public domain - June 2013 waterjuice.org
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  IMPORTS
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

#include "WjCryptLib_Rc4.h"
#include <stdlib.h>

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  INTERNAL FUNCTIONS
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

#define SwapBytes( Value1, Value2 )                 \
{                                                   \
    uint8_t temp = Value1;                          \
    Value1 = Value2;                                \
    Value2 = temp;                                  \
}

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  PUBLIC FUNCTIONS
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Initialise
//
//  Initialises an RC4 cipher and discards the specified number of first bytes. KeySize must be in the range 1 to 256
//  inclusive.
//  Returns 0 if successful, or -1 if KeySize is 0.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
int
    Rc4Initialise
    (
        Rc4Context*     Context,        // [out]
        void const*     Key,            // [in]
        uint32_t        KeySize,        // [in]
        uint32_t        DropN           // [in]
    )
{
    uint32_t        i;
    uint32_t        j;
    uint32_t        n;

    if( 0 == KeySize )
    {
        // RC4 is undefined for a zero length key. Refuse to initialise.
        return -1;
    }

    // Setup key schedule
    for( i=0; i<256; i++ )
    {
        Context->S[i] = (uint8_t)i;
    }

    j = 0;
    for( i=0; i<256; i++ )
    {
        j = ( j + Context->S[i] + ((uint8_t*)Key)[i % KeySize] ) % 256;
        SwapBytes( Context->S[i], Context->S[j] );
    }

    i = 0;
    j = 0;

    // Drop first bytes (if requested)
    for( n=0; n<DropN; n++ )
    {
        i = ( i + 1 ) % 256;
        j = ( j + Context->S[i] ) % 256;
        SwapBytes( Context->S[i], Context->S[j] );
    }

    Context->i = i;
    Context->j = j;

    return 0;
}

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Output
//
//  Outputs the requested number of bytes from the RC4 stream
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void
    Rc4Output
    (
        Rc4Context*     Context,        // [in out]
        void*           Buffer,         // [out]
        uint32_t        Size            // [in]
    )
{
    uint32_t    n;

    for( n=0; n<Size; n++ )
    {
        Context->i = ( Context->i + 1 ) % 256;
        Context->j = ( Context->j + Context->S[Context->i] ) % 256;
        SwapBytes( Context->S[Context->i], Context->S[Context->j] );

        ((uint8_t*)Buffer)[n] = Context->S[ (Context->S[Context->i] + Context->S[Context->j]) % 256 ];
    }
}

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4Xor
//
//  XORs the RC4 stream with an input buffer and puts the results in an output buffer. This is used for encrypting
//  and decrypting data. InBuffer and OutBuffer can point to the same location for inplace encrypting/decrypting
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void
    Rc4Xor
    (
        Rc4Context*     Context,        // [in out]
        void const*     InBuffer,       // [in]
        void*           OutBuffer,      // [out]
        uint32_t        Size            // [in]
    )
{
    uint32_t    n;

    for( n=0; n<Size; n++ )
    {
        Context->i = ( Context->i + 1 ) % 256;
        Context->j = ( Context->j + Context->S[Context->i] ) % 256;
        SwapBytes( Context->S[Context->i], Context->S[Context->j] );

        ((uint8_t*)OutBuffer)[n] = ((uint8_t*)InBuffer)[n]
            ^ ( Context->S[ (Context->S[Context->i] + Context->S[Context->j]) % 256 ] );
    }
}

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//  Rc4XorWithKey
//
//  This function combines Rc4Initialise and Rc4Xor. This is suitable when encrypting/decrypting data in one go with a
//  key that is not going to be reused.
//  InBuffer and OutBuffer can point to the same location for inplace encrypting/decrypting.
//  Returns 0 if successful, or -1 if KeySize is 0.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
int
    Rc4XorWithKey
    (
        uint8_t const*      Key,                    // [in]
        uint32_t            KeySize,                // [in]
        uint32_t            DropN,                  // [in]
        void const*         InBuffer,               // [in]
        void*               OutBuffer,              // [out]
        uint32_t            BufferSize              // [in]
    )
{
    Rc4Context      context;

    if( 0 != Rc4Initialise( &context, Key, KeySize, DropN ) )
    {
        return -1;
    }
    Rc4Xor( &context, InBuffer, OutBuffer, BufferSize );
    return 0;
}


### 薄命令行驱动 rc4_decrypt_cli.c（本项目自写 harness，非上游）
// rc4_decrypt_cli.c
//
// Thin command-line harness (NOT upstream). It decrypts an RC4-obfuscated blob
// with a caller-supplied key, mirroring the real offensive/defensive task of
// extracting a malware configuration / deobfuscating an embedded string, or of
// solving a CTF RC4 challenge. RC4 is a public, well-documented, broken stream
// cipher; this is a generic dual-use codec, not a weapon, loader, or evasion tool.
//
// The graded translation subject is the upstream public-domain RC4 module
// (WjCryptLib_Rc4.c / WjCryptLib_Rc4.h by waterjuice.org, released into the
// public domain, June 2013). This driver only wires that module to a CLI so the
// program is runnable for the dual-build evaluation; it adds no cryptographic
// logic of its own.
//
// Usage:  program <hex-key> <hex-ciphertext>
// Reads only argv, writes only stdout. No file / network / process access.
//
// Example (public RC4 test vector, key "Key" -> plaintext "Plaintext"):
//   program 4b6579 bbf316e8d940af0ad3      ->   Plaintext

#include "WjCryptLib_Rc4.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Convert one hex digit to its 0..15 value, or -1 if it is not a hex digit.
static int nibble( char c )
{
    if( c >= '0' && c <= '9' ) return c - '0';
    if( c >= 'a' && c <= 'f' ) return c - 'a' + 10;
    if( c >= 'A' && c <= 'F' ) return c - 'A' + 10;
    return -1;
}

// Decode a NUL-terminated hex string into out (capacity outcap bytes).
// Returns the number of bytes written, or -1 on malformed / oversized input.
static int hex_decode( const char* hex, uint8_t* out, size_t outcap )
{
    size_t len = strlen( hex );
    if( len % 2 != 0 )
        return -1;

    size_t nbytes = len / 2;
    if( nbytes > outcap )
        return -1;

    for( size_t i = 0; i < nbytes; i++ )
    {
        int hi = nibble( hex[2 * i] );
        int lo = nibble( hex[2 * i + 1] );
        if( hi < 0 || lo < 0 )
            return -1;
        out[i] = (uint8_t)( ( hi << 4 ) | lo );
    }
    return (int)nbytes;
}

int main( int argc, char** argv )
{
    if( argc != 3 )
    {
        fprintf( stderr, "usage: %s <hex-key> <hex-ciphertext>\n",
                 argc > 0 ? argv[0] : "rc4_decrypt" );
        return 2;
    }

    uint8_t key[256];
    uint8_t cipher[4096];
    uint8_t plain[4096];

    int keylen = hex_decode( argv[1], key, sizeof( key ) );
    if( keylen <= 0 )
    {
        fprintf( stderr, "error: key must be 1..256 bytes of valid hex\n" );
        return 2;
    }

    int clen = hex_decode( argv[2], cipher, sizeof( cipher ) );
    if( clen < 0 )
    {
        fprintf( stderr, "error: ciphertext must be valid hex (<= %u bytes)\n",
                 (unsigned)sizeof( cipher ) );
        return 2;
    }

    if( Rc4XorWithKey( key, (uint32_t)keylen, 0, cipher, plain, (uint32_t)clen ) != 0 )
    {
        fprintf( stderr, "error: RC4 initialisation failed\n" );
        return 1;
    }

    fwrite( plain, 1, (size_t)clen, stdout );
    return 0;
}


